    FI_1_HH_Latch(S1 := TRUE, R := FALSE);
ELSIF FI_1_Scaled <= (FI_1_HH_SP - FI_1_Deadband) THEN
    FI_1_HH_Latch(S1 := FALSE, R := (FI_1_HH_Ack AND (FI_1_Scaled <= (FI_1_HH_SP - FI_1_Deadband))));
END_IF;
FI_1_HH := FI_1_HH_Latch.Q1;

IF FI_1_Scaled >= FI_1_H_SP THEN
    FI_1_H := TRUE;
ELSIF FI_1_Scaled <= (FI_1_H_SP - FI_1_Deadband) THEN
    FI_1_H := FALSE;
END_IF;

