FC_1_Error    := FC_1_SP - FI_1_Scaled;
FC_1_Integral := FC_1_Integral + (FC_1_Ki * FC_1_Error);
IF FC_1_Integral > 100.0 THEN
    FC_1_Integral := 100.0;
ELSIF FC_1_Integral < 0.0 THEN
    FC_1_Integral := 0.0;
END_IF;
FC_1_Output := (FC_1_Kp * FC_1_Error) + FC_1_Integral;
IF FC_1_Output > 100.0 THEN
    FC_1_Output := 100.0;
ELSIF FC_1_Output < 0.0 THEN
    FC_1_Output := 0.0;
END_IF;
V_3_Out := REAL_TO_INT(6554.0 + (FC_1_Output / 100.0) * (32767.0 - 6554.0));

